.eada-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2540;
    background: linear-gradient(165deg, #f7f5fb 0%, #f1eef8 55%, #efeef6 100%);
    border-radius: 18px;
}

.eada-container * {
    box-sizing: border-box;
}

.eada-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #2a1a5e 0%, #3d2a7a 55%, #5b3f9e 100%);
    color: #f6f3ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(42, 26, 94, 0.32);
}

.eada-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.eada-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f1cf78;
    background: rgba(241, 207, 120, 0.13);
    border: 1px solid rgba(241, 207, 120, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.eada-subtitle {
    margin: 0 auto;
    max-width: 830px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ddd4f4;
}

.eada-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.eada-firm {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(43, 37, 64, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.eada-firm-open { border-left: 5px solid #5b3f9e; }
.eada-firm-custom { border-left: 5px solid #c79a2e; }

.eada-firm-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #2a1a5e;
}

.eada-firm-open .eada-firm-name { color: #5b3f9e; }
.eada-firm-custom .eada-firm-name { color: #a87d16; }

.eada-firm-meta {
    font-size: 0.82rem;
    color: #6a6383;
    line-height: 1.4;
}

.eada-firm-plus {
    align-self: center;
    font-size: 1.6rem;
    font-weight: 800;
    color: #5b3f9e;
}

.eada-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #574f70;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.eada-period-counter #currentDay,
.eada-period-counter #maxPeriods {
    font-weight: 800;
    color: #5b3f9e;
}

.eada-round-name {
    background: rgba(91, 63, 158, 0.13);
    color: #4b318a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.eada-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a87d16;
    background: rgba(199, 154, 46, 0.14);
    border: 1px solid rgba(199, 154, 46, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.eada-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.eada-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(43, 37, 64, 0.08);
    border-top: 4px solid #5b3f9e;
}

.eada-card-margin { border-top-color: #5b3f9e; }
.eada-card-fill { border-top-color: #2e8d8a; }
.eada-card-nps { border-top-color: #c79a2e; }
.eada-card-budget { border-top-color: #6a6383; }

.eada-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7b7497;
}

.eada-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a1a5e;
    font-variant-numeric: tabular-nums;
}

.eada-card-margin .eada-value { color: #5b3f9e; }
.eada-card-fill .eada-value { color: #2e8d8a; }
.eada-card-nps .eada-value { color: #a87d16; }
.eada-card-budget .eada-value { color: #574f70; }

.eada-sublabel {
    font-size: 0.76rem;
    color: #8a83a3;
    line-height: 1.35;
}

/* Margin tells the story: red below target, green above. */
.eada-card-margin.eada-margin-danger { border-top-color: #d24a4a; }
.eada-card-margin.eada-margin-danger .eada-value { color: #d24a4a; }
.eada-card-margin.eada-margin-good { border-top-color: #2e8d6b; }
.eada-card-margin.eada-margin-good .eada-value { color: #2e8d6b; }

.eada-card-fill.eada-fill-danger { border-top-color: #d24a4a; }
.eada-card-fill.eada-fill-danger .eada-value { color: #d24a4a; }
.eada-card-fill.eada-fill-good { border-top-color: #2e8d6b; }
.eada-card-fill.eada-fill-good .eada-value { color: #2e8d6b; }

.eada-card-nps.eada-nps-danger { border-top-color: #d24a4a; }
.eada-card-nps.eada-nps-danger .eada-value { color: #d24a4a; }
.eada-card-nps.eada-nps-good { border-top-color: #2e8d6b; }
.eada-card-nps.eada-nps-good .eada-value { color: #2e8d6b; }

.eada-signal-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e6e1f2;
    color: #574f70;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.eada-signal-bar #customDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #a87d16;
    font-weight: 800;
}

.eada-signal-bar.eada-custom-mid #customDisplay { color: #5b3f9e; }
.eada-signal-bar.eada-custom-good #customDisplay { color: #2e8d6b; }

.eada-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #5b3f9e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 37, 64, 0.07);
}

.eada-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.eada-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2a1a5e;
    margin-bottom: 6px;
}

.eada-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463f5e;
}

.eada-briefing-text strong { color: #5b3f9e; }
.eada-briefing-text em { color: #a87d16; font-style: italic; }

.eada-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 37, 64, 0.07);
}

.eada-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2a1a5e;
    border-bottom: 2px solid #ece8f6;
    padding-bottom: 8px;
}

.eada-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3354;
    margin: 14px 0 6px;
}

.eada-container select,
.eada-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc6e0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2b2540;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.eada-container select:focus,
.eada-container input[type="number"]:focus {
    outline: none;
    border-color: #5b3f9e;
    box-shadow: 0 0 0 3px rgba(91, 63, 158, 0.16);
}

.eada-container select option {
    background-color: #ffffff;
    color: #2b2540;
}

.eada-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #5b3f9e;
}

.eada-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #574f70;
    margin-top: 4px;
}

.eada-range-readout span:nth-child(2) {
    color: #5b3f9e;
    font-weight: 800;
}

.eada-hint {
    font-size: 0.8rem;
    color: #8a83a3;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.eada-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.eada-container .btn-primary {
    background: linear-gradient(135deg, #3d2a7a 0%, #5b3f9e 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(61, 42, 122, 0.32);
}

.eada-container .btn-primary:hover {
    filter: brightness(1.08);
}

.eada-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #cdc6e0;
    color: #6a6383;
    background: transparent;
}

.eada-coach {
    background: linear-gradient(160deg, #2a1a5e 0%, #34226b 100%);
    color: #e7e0fa;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(42, 26, 94, 0.26);
}

.eada-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f1cf78;
    margin-bottom: 8px;
}

.eada-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.eada-coach-body strong { color: #c7b3f0; }
.eada-coach-body em { color: #f1cf78; font-style: italic; }

.eada-history,
.eada-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(43, 37, 64, 0.07);
}

.eada-history h3,
.eada-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2a1a5e;
}

.eada-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463f5e;
}

.eada-container table#usfHistoryTable th {
    background: #f1eef8;
    color: #5b3f9e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd5ef;
}

.eada-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efebf7;
    color: #463f5e;
}

.eada-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8fd;
}

.eada-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .eada-container {
        padding: 14px;
    }
    .eada-header h1 {
        font-size: 1.7rem;
    }
    .eada-firms {
        flex-direction: column;
    }
    .eada-firm-plus {
        transform: rotate(90deg);
    }
    .eada-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .eada-value {
        font-size: 2rem;
    }
    .eada-clock {
        margin-left: 0;
    }
    .eada-period-counter {
        font-size: 0.88rem;
    }
    .eada-signal-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .eada-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.pv-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.pv-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.pv-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.pv-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.pv-cm-score strong { color: #4f9bd9; }
.pv-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.pv-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.pv-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.pv-cm-target.pv-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.pv-cm-target.pv-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.pv-cm-tick { font-weight: 700; }
.pv-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.pv-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.pv-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.pv-cm-metric strong { font-size: 16px; color: #eceff6; }
.pv-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.pv-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .pv-cm-metric { min-width: 70px; } .pv-cm-verdict { font-size: 19px; } }

