(function() {
    'use strict';

    class ProgramPivotAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Program Pivot`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EADA-Lima).
            this.START_MARGIN = 26;        // blended contribution margin (%) drifting below target
            this.TARGET_MARGIN = 32;       // board mandate (%)
            this.START_FILL = 64;          // blended portfolio fill rate (%)
            this.BREAKEVEN_FILL = 80;      // open break-even fill rate (%)
            this.START_NPS = 28;           // learner NPS (+28)
            this.BUDGET = 4.0;             // PEN 4,000,000 portfolio-investment budget (S/ M)
            this.CUSTOM_TARGET = 6.0;      // PEN 6,000,000 of anchor custom spend (S/ M)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.START_MARGIN,       // blended contribution margin (%)
                    fill: this.START_FILL,           // portfolio fill rate (%)
                    nps: this.START_NPS,             // learner NPS
                    budgetUsed: 0,                   // S/ M of the 4.0M committed
                    customWon: 0,                    // S/ M of the 6.0M custom mandate secured
                    legacyTrap: false,               // kept defending the declining functional catalog
                    discountSpiral: false,           // bought fill with margin
                    missedCycle: false,              // built in-house and missed the budget cycle / clients
                    underpriced: false,              // won custom by underpricing below the hurdle
                    onesizeDelivery: false,          // all-online or all-f2f instead of matching mode
                    monitorLoop: false,              // standing demand-monitoring loop in place
                    marginHistory: [this.START_MARGIN],
                    fillHistory: [this.START_FILL],
                    npsHistory: [this.START_NPS],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    segment: `protect`,
                    demand: `functional`,
                    discount: `deep`,
                    diagnosis: 40,
                    topics: `legacy`,
                    delivery: `allf2f`,
                    capability: `build`,
                    invest: `4.0`,
                    pricing: `underprice`,
                    attack: `match`,
                    outcomes: `satisfaction`,
                    sequence: `bigbang`,
                    philosophy: `legacy`,
                    defense: `apologize`,
                    monitor: `none`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const se = document.getElementById(`segmentInput`);
                const de = document.getElementById(`demandInput`);
                const di = document.getElementById(`discountInput`);
                const dg = document.getElementById(`diagnosisInput`);
                if (se) decisions.segment = se.value;
                if (de) decisions.demand = de.value;
                if (di) decisions.discount = di.value;
                if (dg) decisions.diagnosis = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const to = document.getElementById(`topicsInput`);
                const dl = document.getElementById(`deliveryInput`);
                const ca = document.getElementById(`capabilityInput`);
                const iv = document.getElementById(`investInput`);
                if (to) decisions.topics = to.value;
                if (dl) decisions.delivery = dl.value;
                if (ca) decisions.capability = ca.value;
                if (iv) decisions.invest = iv.value;
                const invNum = parseFloat(decisions.invest);
                if (!Number.isFinite(invNum) || invNum <= 0) {
                    warn(`warn_invest_value`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`pricingInput`);
                const at = document.getElementById(`attackInput`);
                const ou = document.getElementById(`outcomesInput`);
                const sq = document.getElementById(`sequenceInput`);
                if (pr) decisions.pricing = pr.value;
                if (at) decisions.attack = at.value;
                if (ou) decisions.outcomes = ou.value;
                if (sq) decisions.sequence = sq.value;
                if (!decisions.pricing) { warn(`warn_pricing_missing`); return false; }
            } else if (round === 4) {
                const ph = document.getElementById(`philosophyInput`);
                const df = document.getElementById(`defenseInput`);
                const mo = document.getElementById(`monitorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ph) decisions.philosophy = ph.value;
                if (df) decisions.defense = df.value;
                if (mo) decisions.monitor = mo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, fillDelta = 0, npsDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the portfolio (Common Error 1: defend the legacy catalog).
                switch (d.segment) {
                    case `gridcall`: marginDelta += 1.5; fillDelta += 3; npsDelta += 2; coachKey = `coach_r1_grid`; break;
                    case `protect`: marginDelta -= 1.5; fillDelta -= 2; npsDelta -= 2; ds.legacyTrap = true; coachKey = `coach_r1_protect`; break;
                    case `retireall`: fillDelta -= 1; npsDelta -= 1; coachKey = `coach_r1_retireall`; break;
                }

                switch (d.demand) {
                    case `emerging`: fillDelta += 3; npsDelta += 3; coachKey = (d.segment === `gridcall`) ? `coach_r1_sharp` : coachKey; break;
                    case `functional`: fillDelta -= 3; npsDelta -= 2; ds.legacyTrap = true; if (coachKey === `coach_default`) coachKey = `coach_r1_functional`; break;
                    case `price`: marginDelta -= 2; npsDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_price`; break;
                }

                // Discounting to fill seats (Common Error 2).
                switch (d.discount) {
                    case `hold`: marginDelta += 2.5; npsDelta += 1; break;
                    case `some`: marginDelta -= 1.5; fillDelta += 3; break;
                    case `deep`: marginDelta -= 5; fillDelta += 8; ds.discountSpiral = true; coachKey = `coach_r1_discount`; break;
                }

                // Diagnosis depth — a sharper read makes the redesign land better next round.
                if (d.diagnosis >= 60) { npsDelta += 1; fillDelta += 1; }
                else if (d.diagnosis <= 25) { npsDelta -= 1; }

                summaryKey = (d.segment === `gridcall` && d.demand === `emerging` && d.discount !== `deep`) ? `sum_r1_good` :
                             (d.discount === `deep` ? `sum_r1_discount` : `sum_r1_weak`);
            } else if (round === 2) {
                // The heart: topics, delivery, build/buy/partner, investment.
                const invest = parseFloat(d.invest);

                // Topic mix (Common Error 1).
                switch (d.topics) {
                    case `emerging`: fillDelta += 7; npsDelta += 6; marginDelta += 1; coachKey = `coach_r2_emerging`; break;
                    case `legacy`: fillDelta -= 6; npsDelta -= 5; ds.legacyTrap = true; coachKey = `coach_r2_legacy`; break;
                    case `everything`: fillDelta += 2; marginDelta -= 2; coachKey = `coach_r2_everything`; break;
                }

                // Delivery-mode fit (Common Error 5).
                switch (d.delivery) {
                    case `matched`: fillDelta += 6; npsDelta += 5; marginDelta += 2; break;
                    case `allonline`: marginDelta += 3; fillDelta += 2; npsDelta -= 9; ds.onesizeDelivery = true; coachKey = `coach_r2_online`; break;
                    case `allf2f`: marginDelta -= 3; fillDelta -= 5; npsDelta += 1; ds.onesizeDelivery = true; coachKey = `coach_r2_f2f`; break;
                }

                // Build vs buy vs partner (Common Error 3) — speed/margin trade-off.
                switch (d.capability) {
                    case `partner`: fillDelta += 4; npsDelta += 3; marginDelta -= 1; break;          // fast to demand, shares some margin
                    case `buy`: fillDelta += 3; marginDelta -= 2; npsDelta += 1; break;               // fastest, shares most margin
                    case `build`: marginDelta += 2; fillDelta -= 4; npsDelta -= 2; ds.missedCycle = true; coachKey = `coach_r2_build`; break; // owns margin, misses the cycle
                }

                // Investment level vs budget cap.
                ds.budgetUsed = Math.min(this.BUDGET, Math.round((ds.budgetUsed + invest) * 10) / 10);
                if (invest >= 4.0) {
                    // Spending the whole budget at once on a build strategy is the over-reach.
                    marginDelta -= 1; fillDelta -= 1;
                    if (d.capability === `build`) { marginDelta -= 1; coachKey = `coach_r2_overspend`; }
                } else if (invest <= 1.2) {
                    fillDelta -= 2; npsDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r2_underinvest`;
                } else {
                    fillDelta += 2; marginDelta += 1;
                }

                summaryKey = (d.topics === `emerging` && d.delivery === `matched` && (d.capability === `partner` || d.capability === `buy`)) ? `sum_r2_good` :
                             (d.topics === `legacy` ? `sum_r2_legacy` :
                             (ds.onesizeDelivery ? `sum_r2_onesize` :
                             (d.capability === `build` ? `sum_r2_build` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Win the custom bids and respond to the price attack.
                // Pricing the RFPs (Common Error 4: underprice to win logos).
                let won = 0;
                switch (d.pricing) {
                    case `hurdle`: marginDelta += 3; won = this.CUSTOM_TARGET; npsDelta += 2; break;       // win both at/above the hurdle
                    case `underprice`: marginDelta -= 4; won = this.CUSTOM_TARGET; ds.underpriced = true; coachKey = `coach_r3_underprice`; break; // win logos, lose margin
                    case `premium`: marginDelta += 2; won = this.CUSTOM_TARGET * 0.5; coachKey = `coach_r3_premium`; break;  // hold margin, win only one
                }

                // Competitive price attack on online functional programs (Common Error 5 / decision tree #2).
                switch (d.attack) {
                    case `differentiate`: marginDelta += 2; npsDelta += 3; fillDelta += 3; coachKey = (d.pricing === `hurdle`) ? `coach_r3_strong` : coachKey; break;
                    case `match`: marginDelta -= 5; fillDelta += 2; ds.discountSpiral = true; if (coachKey === `coach_default`) coachKey = `coach_r3_match`; break;
                    case `cede`: marginDelta += 1; fillDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_cede`; break;
                }

                // Outcome measurement as a contract condition.
                switch (d.outcomes) {
                    case `design`: npsDelta += 4; marginDelta += 1; break;
                    case `promise`: npsDelta -= 2; won = Math.max(0, won - this.CUSTOM_TARGET * 0.25); if (coachKey === `coach_default`) coachKey = `coach_r3_promise`; break;
                    case `satisfaction`: npsDelta -= 3; won = Math.max(0, won - this.CUSTOM_TARGET * 0.5); if (coachKey === `coach_default`) coachKey = `coach_r3_satisfaction`; break;
                }

                // Launch sequencing within faculty/partner capacity.
                switch (d.sequence) {
                    case `staged`: fillDelta += 3; npsDelta += 2; marginDelta += 1; break;
                    case `custom`: marginDelta += 1; fillDelta -= 5; npsDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_customlock`; break;
                    case `bigbang`: npsDelta -= 4; fillDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_bigbang`; break;
                }

                ds.customWon = Math.max(0, Math.round(won * 10) / 10);

                summaryKey = (d.pricing === `hurdle` && d.attack === `differentiate` && d.outcomes === `design`) ? `sum_r3_good` :
                             (d.pricing === `underprice` ? `sum_r3_underprice` :
                             (d.attack === `match` ? `sum_r3_match` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover and defend the strategy.
                switch (d.philosophy) {
                    case `demand`: marginDelta += 2; fillDelta += 3; npsDelta += 3; coachKey = `coach_r4_demand`; break;
                    case `legacy`: marginDelta -= 2; fillDelta -= 4; npsDelta -= 3; ds.legacyTrap = true; coachKey = `coach_r4_legacy`; break;
                    case `cheapest`: marginDelta -= 4; fillDelta += 1; npsDelta -= 2; ds.discountSpiral = true; coachKey = `coach_r4_cheapest`; break;
                }

                switch (d.defense) {
                    case `speed`: marginDelta += 1; npsDelta += 2; fillDelta += 2; if (d.philosophy === `demand`) coachKey = `coach_r4_speed`; break;
                    case `margin`: npsDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r4_marginonly`; break;
                    case `apologize`: marginDelta -= 2; npsDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r4_apologize`; break;
                }

                switch (d.monitor) {
                    case `loop`: fillDelta += 3; npsDelta += 3; ds.monitorLoop = true; break;
                    case `annual`: fillDelta += 1; break;
                    case `none`: fillDelta -= 2; npsDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r4_nomonitor`; break;
                }

                if (d.conviction >= 60) { npsDelta += 1; fillDelta += 1; }
                else if (d.conviction <= 25) { npsDelta -= 1; }

                summaryKey = (d.philosophy === `demand` && d.defense === `speed` && d.monitor === `loop`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.margin = Math.max(0, Math.min(60, Math.round((ds.margin + marginDelta) * 10) / 10));
            ds.fill = Math.max(0, Math.min(100, Math.round((ds.fill + fillDelta) * 10) / 10));
            ds.nps = Math.max(-100, Math.min(100, Math.round(ds.nps + npsDelta)));

            // Compounding penalties from structural traps.
            // The legacy trap erodes fill and NPS over time (the model loses relevance).
            if (ds.legacyTrap && round >= 2) { ds.fill = Math.max(0, ds.fill - 1); ds.nps = Math.max(-100, ds.nps - 1); }
            // The discount spiral trains the market — margin keeps bleeding.
            if (ds.discountSpiral && round >= 2) { ds.margin = Math.max(0, ds.margin - 1); }

            ds.marginHistory.push(ds.margin);
            ds.fillHistory.push(ds.fill);
            ds.npsHistory.push(ds.nps);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                fill: ds.fill,
                fillDelta: Math.round(fillDelta * 10) / 10,
                nps: ds.nps,
                npsDelta: Math.round(npsDelta),
                budgetUsed: ds.budgetUsed,
                customWon: ds.customWon,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.eada-card-margin`);
                if (card) {
                    card.classList.toggle(`eada-margin-danger`, n < self.TARGET_MARGIN);
                    card.classList.toggle(`eada-margin-good`, n >= self.TARGET_MARGIN);
                }
                return `${self._fmtNum(n, 1)}%`;
            });

            uiManager.bind(`fillDisplay`, `domainState.fill`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.eada-card-fill`);
                if (card) {
                    card.classList.toggle(`eada-fill-danger`, n < 70);
                    card.classList.toggle(`eada-fill-good`, n >= self.BREAKEVEN_FILL);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`npsDisplay`, `domainState.nps`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.eada-card-nps`);
                if (card) {
                    card.classList.toggle(`eada-nps-danger`, n < 20);
                    card.classList.toggle(`eada-nps-good`, n >= 40);
                }
                return (n > 0 ? `+` : ``) + n;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => `S/ ${self._fmtNum(Number(v), 1)}M`);

            uiManager.bind(`customDisplay`, `domainState.customWon`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.eada-signal-bar`);
                if (bar) {
                    bar.classList.toggle(`eada-custom-mid`, n > 0 && n < self.CUSTOM_TARGET);
                    bar.classList.toggle(`eada-custom-good`, n >= self.CUSTOM_TARGET);
                }
                return `S/ ${self._fmtNum(n, 1)}M`;
            });

            // Diagnosis-depth slider readout.
            const dg = document.getElementById(`diagnosisInput`);
            const dgReadout = document.getElementById(`diagnosisReadout`);
            if (dg && dgReadout) {
                dgReadout.textContent = dg.value;
                dg.addEventListener(`input`, function() { dgReadout.textContent = dg.value; });
            }
        }

        _fmtNum(v, decimals) {
            // Locale-aware decimal: en "2.4", es "2,4".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(decimals);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

