        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.marginHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                pivotChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.marginHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.fillHistory.map((v) => Math.round(v)) },
                        { data: ds.npsHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (KPI scoring + weights unchanged).
            const margin = Math.round(ds.margin * 10) / 10;
            const fill = Math.round(ds.fill);
            const nps = Math.round(ds.nps);
            const customWon = Math.round(ds.customWon * 10) / 10;
            const marginScore = Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 100));
            const fillScore = Math.max(0, Math.min(100, (fill / this.BREAKEVEN_FILL) * 100));
            const npsScore = Math.max(0, Math.min(100, (nps + 100) / 2));
            const customScore = Math.max(0, Math.min(100, (customWon / this.CUSTOM_TARGET) * 100));
            return Math.round(marginScore * 0.30 + fillScore * 0.26 + npsScore * 0.22 + customScore * 0.22);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="pv-cm-target ' + (ok ? 'pv-cm-met' : 'pv-cm-missed') + '">'
                    + '<span class="pv-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.onHurdle, t('tgt_margin'))
                + chip(!!summary.filledWell, t('tgt_fill'))
                + chip(!!summary.lovedAgain, t('tgt_nps'))
                + chip(!!summary.wonCustom, t('tgt_custom'))
                + chip(!!summary.cleanPivot, t('tgt_clean'));
            const metric = function (label, val) {
                return '<div class="pv-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_margin'), nz(summary.margin) + '%')
                + metric(t('kpi_fill'), nz(summary.fill) + '%')
                + metric(t('kpi_nps'), nz(summary.nps))
                + metric(t('kpi_custom'), 'S/' + nz(summary.customWon) + 'M');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="pv-cm">'
                +   '<div class="pv-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="pv-cm-verdict">' + verdict + '</div>'
                +   '<div class="pv-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="pv-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="pv-cm-targets">' + targets + '</div>'
                +   '<div class="pv-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="pv-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin * 10) / 10;
            const fill = Math.round(ds.fill);
            const nps = Math.round(ds.nps);
            const customWon = Math.round(ds.customWon * 10) / 10;

            const onHurdle = margin >= this.TARGET_MARGIN;
            const filledWell = fill >= this.BREAKEVEN_FILL;
            const lovedAgain = nps >= 40;
            const wonCustom = customWon >= this.CUSTOM_TARGET;

            // Composite: margin, fill, NPS, custom mandate — balanced portfolio health.
            const marginScore = Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 100));
            const fillScore = Math.max(0, Math.min(100, (fill / this.BREAKEVEN_FILL) * 100));
            const npsScore = Math.max(0, Math.min(100, (nps + 100) / 2));
            const customScore = Math.max(0, Math.min(100, (customWon / this.CUSTOM_TARGET) * 100));
            // v1.1.0 FIX A - composite delegated to _composite(ds); marginScore/fillScore/npsScore/customScore
            // locals above are left in place (now unused, harmless) to keep the scoring diff minimal.
            const composite = this._composite(ds);

            // A genuine pivot means NONE of the five headline anti-patterns was
            // committed. Each flag maps to one Common Error / Decision-Tree branch,
            // so any one of them disqualifies the top verdict even if the KPIs
            // were otherwise rescued — exactly what the facilitator debrief teaches.
            const cleanPivot = !ds.legacyTrap && !ds.discountSpiral && !ds.missedCycle &&
                               !ds.underpriced && !ds.onesizeDelivery;

            let pattern = `mixed`;
            if (ds.legacyTrap && !onHurdle && !filledWell) pattern = `legacy`;
            else if (ds.discountSpiral && !onHurdle) pattern = `discount`;
            else if (ds.missedCycle && !wonCustom) pattern = `missed`;
            else if (ds.underpriced) pattern = `underpriced`;
            else if (ds.onesizeDelivery) pattern = `onesize`;
            else if (ds.missedCycle) pattern = `missed`;
            else if (ds.legacyTrap) pattern = `legacy`;
            else if (ds.discountSpiral) pattern = `discount`;
            else if (cleanPivot && onHurdle && filledWell && lovedAgain && wonCustom) pattern = `pivot`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_eroding`;
            if (cleanPivot && onHurdle && filledWell && lovedAgain && wonCustom && composite >= 78) perfKey = `grade_pivot`;
            else if (onHurdle && wonCustom && pattern !== `discount` && pattern !== `underpriced`) perfKey = `grade_margin`;
            else if (ds.legacyTrap && !filledWell) perfKey = `grade_legacy`;
            else if ((ds.discountSpiral || ds.underpriced) && !onHurdle) perfKey = `grade_bought`;
            else if (ds.missedCycle && !wonCustom) perfKey = `grade_missed`;
            else if (composite >= 55) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `pivot`) insights.push(window.mySimulation.t(`insight_pivot`));
            else if (pattern === `legacy`) insights.push(window.mySimulation.t(`insight_legacy`));
            else if (pattern === `discount`) insights.push(window.mySimulation.t(`insight_discount`));
            else if (pattern === `missed`) insights.push(window.mySimulation.t(`insight_missed`));
            else if (pattern === `underpriced`) insights.push(window.mySimulation.t(`insight_underpriced`));
            else if (pattern === `onesize`) insights.push(window.mySimulation.t(`insight_onesize`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!onHurdle) insights.push(window.mySimulation.t(`insight_margin_low`));
            if (!filledWell) insights.push(window.mySimulation.t(`insight_fill_low`));
            if (nps < 25) insights.push(window.mySimulation.t(`insight_nps_low`));
            if (!wonCustom) insights.push(window.mySimulation.t(`insight_custom_lost`));
            if (ds.monitorLoop && pattern === `pivot`) insights.push(window.mySimulation.t(`insight_monitor`));

            return {
                gradeKey: perfKey,
                score: composite,
                cleanPivot: cleanPivot,
                margin: margin,
                fill: fill,
                nps: nps,
                customWon: customWon,
                onHurdle: onHurdle,
                filledWell: filledWell,
                lovedAgain: lovedAgain,
                wonCustom: wonCustom,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.discountSpiral && ds.margin < this.TARGET_MARGIN) return window.mySimulation.t(`hint_discount`);
            if (ds.legacyTrap && ds.fill < 70) return window.mySimulation.t(`hint_legacy`);
            if (ds.missedCycle && ds.customWon < this.CUSTOM_TARGET && state.currentPeriod >= 3) return window.mySimulation.t(`hint_missed`);
            if (ds.underpriced && ds.margin < this.TARGET_MARGIN) return window.mySimulation.t(`hint_underpriced`);
            if (ds.onesizeDelivery && ds.nps < 25) return window.mySimulation.t(`hint_onesize`);
            if (ds.margin >= this.TARGET_MARGIN && ds.fill >= this.BREAKEVEN_FILL && ds.nps >= 40) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => `${self._fmtNum(Number(v), 1)}%` },
                { key: `results.fill`, label: `Fill`, i18nKey: `col_fill`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.nps`, label: `NPS`, i18nKey: `col_nps`, formatter: (v) => (Number(v) > 0 ? `+` : ``) + Math.round(v) },
                { key: `results.customWon`, label: `Custom`, i18nKey: `col_custom`, formatter: (v) => `S/ ${self._fmtNum(Number(v), 1)}M` }
            ];
